import fs from "node:fs";
import path from "node:path";
import type { StoreApi } from "zustand";
import type { AppState } from "@/lib/state/app-state-types";
import { test, expect } from "../../fixtures/test-base";
import { prepareDenseComparisonFixture } from "../../helpers/dense-comparison-fixture";
import { prepareDenseStream } from "../../helpers/dense-canonical-stream";
import { verifyDenseThreadsFiles } from "../../helpers/dense-threads-fixture";
import { loadDenseCold } from "../../helpers/dense-cold-load";
import { captureDenseTraffic } from "../../helpers/dense-measurement";
import { dwell } from "../../helpers/causal-waits";
import { sha256File } from "../../helpers/dense-snapshot";
import type { Page, Browser } from "@playwright/test";

type AnimationPhase = "boot" | "calibration" | "idle" | "streaming";
type AnimationProbeApi = {
  phase: (value: AnimationPhase) => void;
  snapshot: () => Promise<AnimationSnapshot>;
  stop: () => { births: Record<string, unknown>[]; restoredAnimate: boolean };
};
type AnimationSnapshot = {
  phase: AnimationPhase;
  at: number;
  timedOut: boolean;
  targets: number;
  intersections: number;
  animations: Record<string, unknown>[];
  running: number;
  paused: number;
  unobservable: number;
};
type AnimationProbeWindow = Window & { __kandevAnimationProbe: AnimationProbeApi };

function installAnimationProbe() {
  const original = Element.prototype.animate;
  const ids = new WeakMap<object, number>();
  let nextId = 1;
  let phase: AnimationPhase = "boot";
  const births: Record<string, unknown>[] = [];
  const identify = (value: object) => {
    let id = ids.get(value);
    if (id === undefined) {
      id = nextId++;
      ids.set(value, id);
    }
    return id;
  };
  const describe = (element: Element) => {
    let owner = element;
    let kind = "other";
    const grid = element.closest(".spinner-grid");
    if (grid) {
      owner = grid;
      kind = "grid-spinner";
    } else if (element.hasAttribute("data-compositor-spin")) kind = "compositor-spin";
    else if (element.hasAttribute("data-compositor-pulse")) kind = "compositor-pulse";
    const tile = element.closest('[data-testid^="thread-column-"]');
    return {
      targetId: identify(element),
      ownerId: identify(owner),
      kind,
      tag: element.tagName,
      className: element.getAttribute("class"),
      ownerClassName: owner.getAttribute("class"),
      calibration: element.getAttribute("data-animation-calibration"),
      tile: tile?.getAttribute("data-testid") ?? null,
      owner,
    };
  };
  const wrapped = function (this: Element, ...args: Parameters<Element["animate"]>) {
    const animation = original.apply(this, args);
    const { owner: _owner, ...description } = describe(this);
    births.push({ phase, at: performance.now(), animationId: identify(animation), ...description });
    return animation;
  };
  Element.prototype.animate = wrapped;
  const snapshot = async (): Promise<AnimationSnapshot> => {
    const at = performance.now();
    const animations = document.getAnimations();
    const targets = new Set<Element>();
    const records = animations.map((animation) => {
      const effect = animation.effect as KeyframeEffect | null;
      const target = effect?.target;
      if (!(target instanceof Element)) return { animation, target: null, owner: null };
      const owner = describe(target).owner;
      targets.add(target);
      targets.add(owner);
      return { animation, target, owner };
    });
    const intersections = new Map<Element, Record<string, unknown>>();
    const timedOut = await new Promise<boolean>((resolve) => {
      if (!targets.size) {
        resolve(false);
        return;
      }
      const observer = new IntersectionObserver((entries) => {
        for (const entry of entries) {
          intersections.set(entry.target, {
            isIntersecting: entry.isIntersecting,
            ratio: entry.intersectionRatio,
            width: entry.boundingClientRect.width,
            height: entry.boundingClientRect.height,
            top: entry.boundingClientRect.top,
            left: entry.boundingClientRect.left,
            intersectionWidth: entry.intersectionRect.width,
            intersectionHeight: entry.intersectionRect.height,
          });
        }
        if (intersections.size !== targets.size) return;
        clearTimeout(timeout);
        observer.disconnect();
        resolve(false);
      });
      const timeout = setTimeout(() => {
        observer.disconnect();
        resolve(true);
      }, 5000);
      for (const target of targets) observer.observe(target);
    });
    return {
      phase,
      at,
      timedOut,
      targets: targets.size,
      intersections: intersections.size,
      running: animations.filter((a) => a.playState === "running").length,
      paused: animations.filter((a) => a.playState === "paused").length,
      unobservable: records.filter((r) => r.target === null).length,
      animations: records.map(({ animation, target, owner }) => {
        const effect = animation.effect as KeyframeEffect | null;
        const timing = effect?.getTiming();
        const base = {
          animationId: identify(animation),
          playState: animation.playState,
          cssName: animation instanceof CSSAnimation ? animation.animationName : null,
          duration: timing?.duration,
          delay: timing?.delay,
          iterations: timing?.iterations === Infinity ? "Infinity" : timing?.iterations,
        };
        if (!target || !owner) return { ...base, target: null };
        const { owner: _owner, ...description } = describe(target);
        return {
          ...base,
          ...description,
          targetIntersection: intersections.get(target),
          ownerIntersection: intersections.get(owner),
        };
      }),
    };
  };
  (window as AnimationProbeWindow).__kandevAnimationProbe = {
    phase(value) {
      phase = value;
    },
    snapshot,
    stop() {
      const owned = Element.prototype.animate === wrapped;
      if (owned) Element.prototype.animate = original;
      return {
        births: structuredClone(births),
        restoredAnimate: owned && Element.prototype.animate === original,
      };
    },
  };
}

async function snapshotAnimations(page: Page) {
  return page.evaluate(() => (window as AnimationProbeWindow).__kandevAnimationProbe.snapshot());
}

async function calibrateAnimationProbe(browser: Browser) {
  const context = await browser.newContext({ viewport: { width: 400, height: 400 } });
  const page = await context.newPage();
  try {
    await page.addInitScript(installAnimationProbe);
    await page.goto("data:text/html,<div></div>");
    await page.evaluate(() => {
      (window as AnimationProbeWindow).__kandevAnimationProbe.phase("calibration");
      const style = document.createElement("style");
      style.textContent = "@keyframes diagnostic-opacity { from {opacity:.6} to {opacity:1} }";
      document.head.append(style);
      const create = (name: string, top: number, left = 0) => {
        const element = document.createElement("div");
        element.dataset.animationCalibration = name;
        Object.assign(element.style, {
          position: "absolute",
          top: `${top}px`,
          left: `${left}px`,
          width: "30px",
          height: "30px",
        });
        document.body.append(element);
        return element;
      };
      const visible = create("visible-waapi", 20);
      const below = create("below-waapi", 800);
      const clipped = create("clipped-waapi", 100);
      const clip = document.createElement("div");
      Object.assign(clip.style, {
        position: "absolute",
        top: "80px",
        left: "0",
        width: "40px",
        height: "40px",
        overflow: "hidden",
      });
      document.body.append(clip);
      clip.append(clipped);
      for (const element of [visible, below, clipped])
        element.animate([{ opacity: 0.6 }, { opacity: 1 }], {
          duration: 1000,
          iterations: Infinity,
        });
      create("visible-css", 150, 150).style.animation = "diagnostic-opacity 1s infinite";
    });
    await page.waitForFunction(() => document.getAnimations().length === 4);
    const snapshot = await snapshotAnimations(page);
    const stop = await page.evaluate(() =>
      (window as AnimationProbeWindow).__kandevAnimationProbe.stop(),
    );
    return { snapshot, stop };
  } finally {
    await context.close();
  }
}

const directory = path.resolve(
  process.cwd(),
  "../../.kandev/diagnostics/dense-workbench-performance",
);

async function loadedHistory(page: Page, sessionIds: string[]) {
  return page.evaluate((ids) => {
    const store = (window as unknown as { __KANDEV_E2E_STORE__: StoreApi<AppState> })
      .__KANDEV_E2E_STORE__;
    return ids.map((sessionId) => ({
      sessionId,
      messages: store.getState().messages.bySession[sessionId]?.length ?? 0,
    }));
  }, sessionIds);
}

test("attributes running animation owners, creation and viewport intersection", async ({
  browser,
  testPage,
  apiClient: api,
  seedData: seed,
  backend,
}, info) => {
  test.setTimeout(600_000);
  fs.mkdirSync(directory, { recursive: true });
  const output = path.join(directory, `animation-attribution-${Date.now()}.json`);
  const report: Record<string, unknown> = {
    measurementKind: "animation-attribution",
    assetsSha256: "9e20f26bcc69f78d90ee9cdd27599f0830ced6f447160391b73d2bdc58d972fa",
    limits:
      "Private diagnostic wraps native Element.animate and takes IntersectionObserver snapshots. Animation creation counts and point-in-time geometry do not establish CPU gains, paint visibility, battery or M2 Air performance. The existing visibility helper already gates document, owner and intersection visibility. No production source or input policy changes.",
  };
  const checkpoint = () => {
    const temporary = output + ".pending";
    fs.writeFileSync(temporary, JSON.stringify(report, null, 2));
    const fd = fs.openSync(temporary, "r");
    fs.fsyncSync(fd);
    fs.closeSync(fd);
    fs.renameSync(temporary, output);
  };
  let stream: Awaited<ReturnType<typeof prepareDenseStream>> | undefined;
  let context: Awaited<ReturnType<Browser["newContext"]>> | undefined;
  let page: Page | undefined;
  let probeActive = false;
  try {
    const calibration = await calibrateAnimationProbe(browser);
    report.calibration = calibration;
    checkpoint();
    expect(calibration.snapshot.timedOut).toBe(false);
    expect(calibration.snapshot.running).toBe(4);
    expect(calibration.snapshot.unobservable).toBe(0);
    expect(calibration.stop.births).toHaveLength(3);
    expect(calibration.stop.restoredAnimate).toBe(true);
    const calibrationRows = calibration.snapshot.animations;
    for (const label of ["visible-waapi", "visible-css"])
      expect(
        calibrationRows.find((row) => row.calibration === label)?.targetIntersection,
      ).toMatchObject({ isIntersecting: true });
    for (const label of ["below-waapi", "clipped-waapi"])
      expect(
        calibrationRows.find((row) => row.calibration === label)?.targetIntersection,
      ).toMatchObject({ isIntersecting: false });
    const prepared = await prepareDenseComparisonFixture(api, seed, backend, testPage);
    report.fixture = prepared.fixture;
    report.fixtureReplay = prepared.provenance;
    checkpoint();
    const database = path.join(backend.tmpDir, "animation-attribution.db");
    fs.copyFileSync(prepared.snapshot, database);
    expect(sha256File(database)).toBe(prepared.provenance?.databaseSha256);
    await backend.restart({
      KANDEV_DATABASE_PATH: database,
      KANDEV_HOME_DIR: path.join(backend.tmpDir, "animation-attribution-home"),
      KANDEV_WEB_DIST_DIR: path.resolve(process.cwd(), "dist"),
      KANDEV_LOG_LEVEL: "warn",
      ...prepared.restartEnv,
    });
    report.filesBefore = await verifyDenseThreadsFiles(api, prepared.backend, prepared.fixture);
    const threads = prepared.fixture.threads.slice(0, 6);
    stream = await prepareDenseStream(
      api,
      prepared.seed,
      prepared.backend,
      threads,
      prepared.sampleNamespace + "animation-attribution",
    );
    context = await browser.newContext({
      baseURL: backend.frontendUrl,
      viewport: { width: 1470, height: 956 },
      deviceScaleFactor: 2,
      locale: "en-US",
    });
    page = await context.newPage();
    await page.addInitScript(installAnimationProbe);
    await page.addInitScript((port) => {
      localStorage.setItem("kandev.onboarding.completed", "true");
      window.__KANDEV_API_PORT = port;
      (window as unknown as { __KANDEV_E2E_EXPOSE_STORE__: boolean }).__KANDEV_E2E_EXPOSE_STORE__ =
        true;
    }, String(backend.port));
    report.cold = await loadDenseCold({
      page,
      workspaceId: prepared.seed.workspaceId,
      threads,
      warmup: stream.warmup,
      traffic: captureDenseTraffic(page),
    });
    const sessionIds = threads.map((thread) => thread.sessionId);
    report.initialLoadedHistory = await loadedHistory(page, sessionIds);
    expect(report.initialLoadedHistory).toEqual(
      sessionIds.map((sessionId) => ({ sessionId, messages: 100 })),
    );
    await page.evaluate(() =>
      (window as AnimationProbeWindow).__kandevAnimationProbe.phase("idle"),
    );
    probeActive = true;
    await dwell(
      page,
      5000,
      "clock-separation",
      "observe animation creation during idle; excluded from speed evidence",
    );
    report.idleSnapshot = await snapshotAnimations(page);
    checkpoint();
    await page.evaluate(() =>
      (window as AnimationProbeWindow).__kandevAnimationProbe.phase("streaming"),
    );
    stream.release();
    await dwell(
      page,
      prepared.fixture.workload.durationMs,
      "clock-separation",
      "observe animation creation during an ordered stream; excluded from speed evidence",
    );
    report.streamingSnapshot = await snapshotAnimations(page);
    report.counts = await page.evaluate(() =>
      (window as AnimationProbeWindow).__kandevAnimationProbe.stop(),
    );
    probeActive = false;
    checkpoint();
    expect((report.counts as { restoredAnimate: boolean }).restoredAnimate).toBe(true);
    for (const name of ["idleSnapshot", "streamingSnapshot"]) {
      const snapshot = report[name] as AnimationSnapshot;
      expect(snapshot.timedOut).toBe(false);
      expect(snapshot.intersections).toBe(snapshot.targets);
      expect(snapshot.running).toBeGreaterThan(0);
    }
    await stream.waitForVisible(page);
    await stream.verify();
    report.scheduledUpdates = stream.scheduledUpdates;
    report.verificationErrors = stream.verificationErrors;
    report.allOrderedUpdatesVerified = true;
    report.finalLoadedHistory = await loadedHistory(page, sessionIds);
    expect(report.finalLoadedHistory).toEqual(report.initialLoadedHistory);
    report.filesAfter = await verifyDenseThreadsFiles(api, prepared.backend, prepared.fixture);
    expect(report.filesAfter).toEqual(report.filesBefore);
  } catch (error) {
    report.error = String(error);
    throw error;
  } finally {
    if (page && probeActive) {
      try {
        report.partialCounts = await page.evaluate(() =>
          (window as AnimationProbeWindow).__kandevAnimationProbe.stop(),
        );
      } catch (error) {
        report.stopError = String(error);
      }
    }
    try {
      await stream?.finish();
    } catch (error) {
      report.finishError = String(error);
    }
    try {
      await context?.close();
    } catch (error) {
      report.closeError = String(error);
    }
    checkpoint();
    await info.attach("animation-attribution", {
      path: output,
      contentType: "application/json",
    });
  }
});
